// usage: const dt = new DayTracker(process.env.DAYTRACKER_TOKEN!);

export type Priority = 'low' | 'medium' | 'high' | 'urgent';

export class DayTracker {
  constructor(private token: string, private baseUrl = '${A}') {}

  private async call<T = any>(path: string, init: RequestInit = {}): Promise<T> {
    const res = await fetch(this.baseUrl + '/api' + path, {
      ...init,
      headers: { 'Content-Type': 'application/json', Authorization: 'Bearer ' + this.token, ...(init.headers || {}) },
    });
    if (!res.ok) throw new Error('DayTracker ' + res.status + ': ' + (await res.text()));
    return res.json();
  }

  /** Call any MCP tool directly (same tools your agent sees). */
  async tool<T = any>(name: string, args: Record<string, unknown> = {}): Promise<T> {
    const r = await this.call('/mcp', {
      method: 'POST',
      body: JSON.stringify({ jsonrpc: '2.0', id: 1, method: 'tools/call', params: { name, arguments: args } }),
    });
    return r.result?.structuredContent ?? r;
  }

  summary(date?: string) { return this.call('/summary' + (date ? '?date=' + date : '')); }

  todos = {
    list: (status: 'open' | 'done' | 'all' = 'open') => this.call('/todos?status=' + status),
    create: (t: { title: string; notes?: string; priority?: Priority; due_at?: string; tags?: string[] }) =>
      this.call('/todos', { method: 'POST', body: JSON.stringify(t) }),
    update: (id: string, patch: Record<string, unknown>) =>
      this.call('/todos', { method: 'PUT', body: JSON.stringify({ id, ...patch }) }),
    complete: (id: string) => this.call('/todos', { method: 'PUT', body: JSON.stringify({ id, status: 'done' }) }),
    remove: (id: string) => this.call('/todos', { method: 'DELETE', body: JSON.stringify({ id }) }),
  };

  activities = {
    list: (fromISO?: string) => this.call('/activities' + (fromISO ? '?from=' + encodeURIComponent(fromISO) : '')),
    log: (a: { title: string; category?: string; duration_min?: number; started_at?: string; ended_at?: string; notes?: string }) =>
      this.call('/activities', { method: 'POST', body: JSON.stringify(a) }),
    start: (title: string, category = 'deep-work') => this.tool('start_activity', { title, category }),
    stop: (notes?: string) => this.tool('stop_activity', { notes }),
  };

  reminders = {
    list: (status: 'pending' | 'fired' | 'all' = 'pending') => this.call('/reminders?status=' + status),
    create: (title: string, remindAtISO: string) =>
      this.call('/reminders', { method: 'POST', body: JSON.stringify({ title, remind_at: remindAtISO }) }),
    remove: (id: string) => this.call('/reminders', { method: 'DELETE', body: JSON.stringify({ id }) }),
  };
}

// --- example ---
